import{_ as n,C as r,o,c as i,ag as t,E as s}from"./chunks/framework.Drp2S_UI.js";const y=JSON.parse('{"title":"Architecture and responsibilities","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/architecture.md","filePath":"en/guide/architecture.md","lastUpdated":1792653875000}'),d={name:"en/guide/architecture.md"};function c(l,e,p,u,h,m){const a=r("MermaidDiagram");return o(),i("div",null,[e[0]||(e[0]=t('<h1 id="architecture-and-responsibilities" tabindex="-1">Architecture and responsibilities <a class="header-anchor" href="#architecture-and-responsibilities" aria-label="Permalink to &quot;Architecture and responsibilities&quot;">​</a></h1><p>This page describes the current 0.1.0 implementation of <code>@herberthe/canvas-editor</code>: HarfBuzz shapes all text and Canvas paints document pages. There is no legacy text fallback, UMD build or selectable SVG page backend. See the <a href="./rendering-pipeline.html">rendering pipeline</a> for execution details.</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2>',3)),s(a,{code:`flowchart TB
  App[Application: toolbar, storage, forms] --> API[Editor / Command / Register / EventBus]
  API --> Lifecycle[EditorLifecycle: readiness and state guards]
  API --> Model[Document elements / Range / History]
  Model --> Draw[Draw: dirty ranges and page scheduling]
  Draw --> Host[LayoutHostAdapter / container layout]
  Host --> Text[TextLayoutService / TextLayoutEngine]
  Text --> Bidi[BiDi, script and style runs]
  Bidi --> HB[HarfBuzzTextShaper]
  HB --> Fonts[FontManager / HarfBuzzRuntime]
  Host --> Geometry[TextLine / Cluster / Caret / object geometry]
  Geometry --> Paint[GlyphRenderer / object painters / Canvas]
  Geometry --> Input[Hit testing, selection and navigation]
  Fonts --> Coverage[Coverage diagnostics / FontDownloadManager]
  Coverage --> Draw
`}),e[1]||(e[1]=t('<p>Arrows show responsibilities and data dependencies, not worker boundaries. HarfBuzz layout currently runs on the main thread. Existing workers support tasks such as word counting and serialization; they are not text layout workers.</p><h2 id="source-map" tabindex="-1">Source map <a class="header-anchor" href="#source-map" aria-label="Permalink to &quot;Source map&quot;">​</a></h2><p>Paths are relative to the repository root. These are internal modules, not supported npm deep imports.</p><table tabindex="0"><thead><tr><th>Module</th><th>Location</th><th>Responsibility</th></tr></thead><tbody><tr><td>Public entry</td><td><code>src/editor/index.ts</code></td><td>Normalize data, assemble modules, create/ready, destruction and exports</td></tr><tr><td>Lifecycle</td><td><code>src/editor/core/EditorLifecycle.ts</code></td><td>Initializing, ready, failed and destroyed states; command guards</td></tr><tr><td>Commands</td><td><code>src/editor/core/command/</code></td><td>Public mutation/query entry points and selection operations</td></tr><tr><td>Scheduling</td><td><code>src/editor/core/draw/Draw.ts</code></td><td>Dirty ranges, container flow, pagination, positions and painting</td></tr><tr><td>Layout hosts</td><td><code>src/editor/core/text-engine-host/</code></td><td>Paragraph bridge, tables, objects, document flow and page chrome</td></tr><tr><td>Typography</td><td><code>src/editor/core/text-engine/</code></td><td>Font binaries, BiDi, HarfBuzz, line breaking, outlines and diagnostics</td></tr><tr><td>Geometry</td><td><code>src/editor/core/layout/</code>, <code>src/editor/interface/Layout.ts</code></td><td>Shared line, glyph, cluster, caret and object geometry</td></tr><tr><td>Interaction</td><td><code>src/editor/core/position/</code>, <code>core/range/</code>, <code>core/listener/</code></td><td>Input events, hit testing, selection, carets and keyboard behavior</td></tr><tr><td>Model/extensions</td><td><code>src/editor/interface/</code>, <code>src/plugins/</code></td><td>Public types, document model and plugin integration</td></tr></tbody></table><h2 id="three-distinct-data-layers" tabindex="-1">Three distinct data layers <a class="header-anchor" href="#three-distinct-data-layers" aria-label="Permalink to &quot;Three distinct data layers&quot;">​</a></h2><ol><li><strong>Persisted document</strong>: header/main/footer, element styles, tables and controls in <code>IEditorData</code>. Use <code>command.getValue()</code> to save business content, rather than persisting internal coordinates or font objects.</li><li><strong>Runtime elements</strong>: normalized and split elements with logical source references, used by editing, history and the layout bridge. A runtime array index is not necessarily a UTF-16 character index: graphemes, surrogate pairs, controls and paragraph markers affect the mapping.</li><li><strong>Layout geometry</strong>: TextLine, glyphs, clusters, carets, inline objects and page positions. Results depend on the current font revision and constraints and must be recomputed when these change.</li></ol><p>Internal <code>LayoutRow</code> views still support container flow and host integration. Keeping “row” in a name does not imply that the old text measurement loop remains. Public row snapshots are detached compatibility DTOs, not inputs to the next layout pass.</p><h2 id="typography-containers-and-paint" tabindex="-1">Typography, containers and paint <a class="header-anchor" href="#typography-containers-and-paint" aria-label="Permalink to &quot;Typography, containers and paint&quot;">​</a></h2><p>HarfBuzz supplies contextual glyph IDs, clusters, advances and offsets. It does not paginate an editor document or split tables. TextLayoutEngine combines bidirectional analysis, font selection and line breaking; TextLayoutService converts font metrics and ink bounds into baselines, line boxes, clusters and carets.</p><p>Container hosts handle columns, available widths, floating-image constraints, table cells and page fragments. Document flow combines header, body and footer. GlyphRenderer paints outlines from real font data; images, formulas, controls and blocks retain dedicated object painters. DOM input proxies, tool overlays and accessibility messages remain part of the application: Canvas-only describes the document page renderer.</p><h2 id="lifecycle-events-and-history" tabindex="-1">Lifecycle, events and history <a class="header-anchor" href="#lifecycle-events-and-history" aria-label="Permalink to &quot;Lifecycle, events and history&quot;">​</a></h2><p>Initialization failures reject ready. Missing glyphs instead keep editable placeholders and produce coverage diagnostics. Registering downloaded fonts changes the font revision, invalidates layout and schedules a new render; it does not simply replace a few painted characters.</p><p>Commands apply business operations. History captures document/selection state for undo and redo; it is not a CRDT or collaborative operation log. Listener exposes single callback slots, while EventBus supports multiple subscribers. The host must release its own subscriptions, toolbar and external resources on unmount.</p><h2 id="extension-and-performance-boundaries" tabindex="-1">Extension and performance boundaries <a class="header-anchor" href="#extension-and-performance-boundaries" aria-label="Permalink to &quot;Extension and performance boundaries&quot;">​</a></h2><p>Integrate through public root exports. Plugins that depend on internal Draw objects, old row coordinates or browser text measurement require adaptation. Upstream package compatibility must be verified individually; see <a href="./font-and-esm-migration.html">migration</a>.</p><p><code>lab.incrementalCompute</code> defaults to false. It reuses unchanged native paragraph layouts, while document flow, pagination and positions still run. Long dirty paragraphs, cache cloning and global flow can make it slower. The <a href="./../../guide/native-release-acceptance.html">final acceptance record</a> contains T23/T24 measurements; performance targets and future SVG designs are not shipped capabilities.</p>',16))])}const b=n(d,[["render",c]]);export{y as __pageData,b as default};
